/** The words that name each mark, checked in order against what a row says about itself. */
const NAMES = [
  ["openai", /\b(openai|chatgpt|codex)\b/],
  ["anthropic", /\banthropic\b/],
  ["claude", /\bclaude\b/],
  ["mistralai", /\bmistral\b/],
  ["openrouter", /\bopen ?router\b/],
  ["deepseek", /\bdeep ?seek\b/],
  ["perplexity", /\b(perplexity|sonar)\b/],
  ["huggingface", /\bhugging ?face\b/],
  ["githubcopilot", /\bcopilot\b/],
  ["github", /\b(github|gh)\b/],
  ["cloudflare", /\bcloudflare\b/],
  ["ollama", /\bollama\b/],
  ["lmstudio", /\blm ?studio\b/],
  ["qwen", /\b(qwen|dashscope)\b/],
  ["moonshotai", /\b(moonshot|kimi)\b/],
  ["vllm", /\bvllm\b/],
  ["telegram", /\btelegram\b/], ["discord", /\bdiscord\b/], ["signal", /\bsignal\b/], ["matrix", /\bmatrix\b/],
  ["mastodon", /\bmastodon\b/], ["bluesky", /\bbluesky\b/], ["reddit", /\breddit\b/], ["mattermost", /\bmattermost\b/],
  ["rocketdotchat", /\brocket ?chat\b/], ["zulip", /\bzulip\b/], ["line", /^line\b|\bline (bot|messaging)\b/], ["viber", /\bviber\b/],
  ["wechat", /\bwechat\b/], ["nextcloud", /\bnextcloud\b/], ["ntfy", /\bntfy\b/], ["homeassistant", /\bhome ?assistant\b/],
  ["xmpp", /\b(xmpp|jabber)\b/], ["mqtt", /\bmqtt\b/], ["keybase", /\bkeybase\b/], ["simplex", /\bsimplex\b/], ["vk", /^vk\b|\bvkontakte\b/],
  ["qq", /^qq\b|\bqq bot\b/], ["guilded", /\bguilded\b/], ["mumble", /\bmumble\b/], ["threema", /\bthreema\b/], ["zalo", /\bzalo\b/],
  ["discourse", /\bdiscourse\b/], ["twitch", /\btwitch\b/], ["synology", /\bsynology\b/],
  ["bitwarden", /\bbitwarden\b/], ["1password", /\b(1password|onepassword)\b/], ["keepassxc", /\bkeepass(xc)?\b/],
];
/** Services shown with a neutral tile: their owners ask for permission first, or no open set carries them. */
const NEUTRAL = [
  ["password", /\b(keychain|credential manager|password|vault|pass)\b/],
  ["mail", /\b(e-?mail|mail|smtp|imap|gmail)\b/],
  ["phone", /\b(sms|twilio|text message)\b/],
  ["chat", /\b(slack|teams|whatsapp|messenger|imessage|webex|google chat|irc|gotify|pumble|flock|twist|revolt|kook|nostr|deltachat|delta chat|pushover|feishu|lark|dingtalk|wecom|x dm|chat|channel|webhook)\b/],
  ["key", /\b(key|token|secret)\b/],
];

/** Lower case, with separators as spaces, so "OPENAI_API_KEY" and "cli-claude-code" read as words. */
const words = (hint) => String(hint ?? "").toLowerCase().replace(/[_\-./:()·]+/g, " ").replace(/\s+/g, " ").trim();

/** The mark for the first hint that names one (a catalog id, a connection's name, a secret's name). */
export function markFor(...hints) {
  for (const hint of hints.map(words).filter(Boolean))
    for (const [slug, pattern] of NAMES) if (pattern.test(hint)) return slug;
  return null;
}
/** The kind of neutral tile for hints no mark answers: "chat", "mail", "phone", "password", "key" or "service". */
export function neutralFor(fallback, ...hints) {
  for (const hint of hints.map(words).filter(Boolean))
    for (const [kind, pattern] of NEUTRAL) if (pattern.test(hint)) return kind;
  return fallback ?? "service";
}

/* The neutral symbols, drawn in the theme's own ink (public/brand-marks.css). */
const SYMBOLS = {
  service: "M12 3v3M12 18v3M3 12h3M18 12h3M6.3 6.3l2.1 2.1M15.6 15.6l2.1 2.1M6.3 17.7l2.1-2.1M15.6 8.4l2.1-2.1M12 9a3 3 0 100 6 3 3 0 000-6z",
  chat: "M4 5h16v11H9l-5 4z",
  mail: "M3 6h18v12H3zM3 7l9 6 9-6",
  phone: "M8 3h8v18H8zM11 18h2",
  password: "M6 11h12v9H6zM9 11V8a3 3 0 016 0v3M12 14v3",
  key: "M14 10a4 4 0 11-2.8-3.8L20 15v3h-3v-2h-2v-2l-3.2-3.2",
};

/** Dark ink on a light colour, white on a dark one, as each owner's own light and dark versions do. */
function inkFor(hex) {
  const [r, g, b] = [0, 2, 4].map((at) => parseInt(hex.slice(at, at + 2), 16));
  return 0.2126 * r + 0.7152 * g + 0.0722 * b > 150 ? "#111111" : "#ffffff";
}
function svg(size) {
  const node = document.createElementNS(SVG, "svg");
  node.setAttribute("viewBox", "0 0 24 24");
  node.setAttribute("width", String(size));
  node.setAttribute("height", String(size));
  node.setAttribute("aria-hidden", "true");
  node.setAttribute("focusable", "false");
  return node;
}

/**
 * Batch 21 (2026-09-20): Brand marks removed per DG-157.
 * Returns null for branded marks. For unknown services, returns only the plain key tile.
 * All other neutral tiles (service, chat, mail, phone, password) are also removed.
 */
export function markTile(hints, { size = 28, fallback = "service", label = "" } = {}) {
  const list = Array.isArray(hints) ? hints : [hints];
  const slug = markFor(...list);

  if (slug) return null;

  // For unknown services, keep only the "key" neutral tile
  const kind = neutralFor(fallback, ...list);
  if (kind !== "key") return null;

  // Create the key tile for unknown services
  const tile = document.createElement("span");
  tile.className = "brand-mark";
  tile.style.setProperty("--mark-size", `${size}px`);
  const glyph = svg(Math.round(size * 0.62));
  const path = document.createElementNS(SVG, "path");

  tile.dataset.neutral = kind;
  tile.classList.add("neutral");
  path.setAttribute("d", SYMBOLS[kind] ?? SYMBOLS.service);
  for (const [name, value] of [["fill", "none"], ["stroke", "currentColor"], ["stroke-width", "1.8"], ["stroke-linecap", "round"], ["stroke-linejoin", "round"]])
    path.setAttribute(name, value);

  glyph.append(path);
  tile.append(glyph);
  if (label) { tile.setAttribute("role", "img"); tile.setAttribute("aria-label", label); }
  else tile.setAttribute("aria-hidden", "true");
  return tile;
}
